{
  "name": "Organizador Financeiro Inteligente",
  "description": "Uma ferramenta simples e poderosa para organizar seu salário mensal em categorias personalizáveis, visualizar gastos com gráficos e manter um histórico de evolução financeira."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface Category {
  id: string;
  name: string;
  percentage: number;
  color: string;
}

export interface HistoryRecord {
  id: string;
  date: string;
  salary: number;
  allocations: {
    name: string;
    value: number;
    percentage: number;
  }[];
}

export type TabType = 'dashboard' | 'settings' | 'history';

import { Category } from './types';

export const INITIAL_CATEGORIES: Category[] = [
  { id: '1', name: 'Lazer', percentage: 25, color: '#3b82f6' }, // Blue-500
  { id: '2', name: 'Gastos Fixos', percentage: 25, color: '#ef4444' }, // Red-500
  { id: '3', name: 'Investimentos', percentage: 25, color: '#10b981' }, // Emerald-500
  { id: '4', name: 'Dívidas', percentage: 25, color: '#f59e0b' }, // Amber-500
];

export const INITIAL_SALARY = 3000;

import React, { useState, useEffect } from 'react';
import { Layout } from './components/Layout';
import { Dashboard } from './components/Dashboard';
import { Settings } from './components/Settings';
import { History } from './components/History';
import { Category, HistoryRecord, TabType } from './types';
import { INITIAL_CATEGORIES, INITIAL_SALARY } from './constants';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<TabType>('dashboard');
  const [salary, setSalary] = useState<number>(INITIAL_SALARY);
  const [categories, setCategories] = useState<Category[]>(INITIAL_CATEGORIES);
  const [history, setHistory] = useState<HistoryRecord[]>([]);

  // Carregar dados salvos do localStorage ao iniciar
  useEffect(() => {
    const savedSalary = localStorage.getItem('fin_salary');
    const savedCategories = localStorage.getItem('fin_categories');
    const savedHistory = localStorage.getItem('fin_history');

    if (savedSalary) setSalary(Number(savedSalary));
    if (savedCategories) setCategories(JSON.parse(savedCategories));
    if (savedHistory) setHistory(JSON.parse(savedHistory));
  }, []);

  // Salvar alterações básicas
  const handleUpdateSettings = (newSalary: number, newCategories: Category[]) => {
    setSalary(newSalary);
    setCategories(newCategories);

    localStorage.setItem('fin_salary', newSalary.toString());
    localStorage.setItem('fin_categories', JSON.stringify(newCategories));

    setActiveTab('dashboard');
  };

  const handleLogMonth = () => {
    const newRecord: HistoryRecord = {
      id: Date.now().toString(),
      date: new Date().toLocaleDateString('pt-BR', { month: 'long', year: 'numeric' }),
      salary: salary,
      allocations: categories.map(cat => ({
        name: cat.name,
        percentage: cat.percentage,
        value: (salary * cat.percentage) / 100
      }))
    };

    const updatedHistory = [newRecord, ...history];
    setHistory(updatedHistory);
    localStorage.setItem('fin_history', JSON.stringify(updatedHistory));
    alert('Mês registrado no histórico com sucesso!');
  };

  const clearHistory = () => {
    if (confirm('Tem certeza que deseja apagar todo o histórico?')) {
      setHistory([]);
      localStorage.removeItem('fin_history');
    }
  };

  return (
    <Layout activeTab={activeTab} setActiveTab={setActiveTab}>
      {activeTab === 'dashboard' && (
        <Dashboard 
          salary={salary} 
          categories={categories} 
          onLogMonth={handleLogMonth}
        />
      )}
      {activeTab === 'settings' && (
        <Settings 
          initialSalary={salary} 
          initialCategories={categories} 
          onSave={handleUpdateSettings} 
        />
      )}
      {activeTab === 'history' && (
        <History 
          history={history} 
          onClear={clearHistory}
        />
      )}
    </Layout>
  );
};

export default App;

import React from 'react';
