import React from 'react';
import { PieChart, Pie, Cell, ResponsiveContainer, Tooltip, Legend } from 'recharts';
import { Category } from '../types';
import { TrendingUp, PlusCircle } from 'lucide-react';

interface DashboardProps {
  salary: number;
  categories: Category[];
  onLogMonth: () => void;
}

export const Dashboard: React.FC<DashboardProps> = ({ salary, categories, onLogMonth }) => {
  const chartData = categories.map(cat => ({
    name: cat.name,
    value: cat.percentage,
    amount: (salary * cat.percentage) / 100,
    color: cat.color
  }));

  const formatCurrency = (value: number) => {
    return new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(value);
  };

  return (
    <div className="space-y-6 animate-fadeIn">
      {/* Salary Overview Card */}
      <div className="bg-emerald-50 p-6 rounded-2xl border border-emerald-100 flex justify-between items-center">
        <div>
          <p className="text-emerald-700 text-sm font-medium">Salário Planejado</p>
          <h2 className="text-3xl font-bold text-emerald-900">{formatCurrency(salary)}</h2>
        </div>
        <button 
          onClick={onLogMonth}
          className="bg-emerald-600 hover:bg-emerald-700 text-white p-3 rounded-xl transition-all shadow-md active:scale-95 flex items-center gap-2"
          title="Registrar mês no histórico"
        >
          <PlusCircle size={20} />
          <span className="hidden sm:inline font-medium">Registrar Mês</span>
        </button>
      </div>

      {/* Chart Section */}
      <div className="bg-white p-4 rounded-2xl border border-slate-100 shadow-sm flex flex-col items-center">
        <h3 className="text-slate-500 text-sm font-semibold mb-2 self-start uppercase tracking-widest">Divisão de Gastos</h3>
        <div className="w-full h-64">
          <ResponsiveContainer width="100%" height="100%">
            <PieChart>
              <Pie
                data={chartData}
                cx="50%"
                cy="50%"
                innerRadius={60}
                outerRadius={80}
                paddingAngle={5}
                dataKey="value"
                stroke="none"
              >
                {chartData.map((entry, index) => (
                  <Cell key={`cell-${index}`} fill={entry.color} />
                ))}
              </Pie>
              <Tooltip 
                formatter={(value: number) => [`${value}%`, 'Porcentagem']}
                contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 10px 15px -3px rgba(0,0,0,0.1)' }}
              />
            </PieChart>
          </ResponsiveContainer>
        </div>
      </div>

      {/* List Section */}
      <div className="space-y-3">
        <div className="flex justify-between items-center px-2">
          <h3 className="text-slate-500 text-sm font-semibold uppercase tracking-widest">Detalhes</h3>
          <TrendingUp size={16} className="text-slate-400" />
        </div>

        {chartData.map((cat, idx) => (
          <div 
            key={idx} 
            className="flex items-center justify-between p-4 bg-white rounded-xl border border-slate-100 shadow-sm hover:shadow-md transition-shadow"
          >
            <div className="flex items-center gap-4">
              <div 
                className="w-3 h-10 rounded-full" 
                style={{ backgroundColor: cat.color }} 
              />
              <div>
                <p className="font-semibold text-slate-800">{cat.name}</p>
                <p className="text-slate-500 text-xs font-medium">{cat.value}% do total</p>
              </div>
            </div>
            <div className="text-right">
              <p className="font-bold text-slate-900">{formatCurrency(cat.amount)}</p>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Category } from '../types';
import { Save, AlertCircle, RefreshCcw } from 'lucide-react';

interface SettingsProps {
  initialSalary: number;
  initialCategories: Category[];
  onSave: (salary: number, categories: Category[]) => void;
}

export const Settings: React.FC<SettingsProps> = ({ initialSalary, initialCategories, onSave }) => {
  const [salary, setSalary] = useState<number>(initialSalary);
  const [categories, setCategories] = useState<Category[]>(initialCategories);
  const [totalPercentage, setTotalPercentage] = useState<number>(0);

  useEffect(() => {
    const total = categories.reduce((acc, cat) => acc + cat.percentage, 0);
    setTotalPercentage(total);
  }, [categories]);

  const handlePercentageChange = (id: string, value: string) => {
    const numValue = Math.max(0, Math.min(100, Number(value) || 0));
    setCategories(prev => prev.map(cat => 
      cat.id === id ? { ...cat, percentage: numValue } : cat
    ));
  };

  const handleReset = () => {
    setSalary(3000);
    setCategories(initialCategories.map(cat => ({ ...cat, percentage: 25 })));
  };

  const isValid = totalPercentage === 100;

  return (
    <div className="space-y-6 animate-fadeIn">
      {/* Salary Input */}
      <section className="bg-white p-6 rounded-2xl border border-slate-100 shadow-sm space-y-4">
        <label className="block">
          <span className="text-slate-500 text-sm font-semibold uppercase tracking-widest mb-2 block">Salário Mensal (R$)</span>
          <input 
            type="number" 
            value={salary}
            onChange={(e) => setSalary(Number(e.target.value))}
            placeholder="Ex: 5000"
            className="w-full text-2xl font-bold p-4 bg-slate-50 rounded-xl border-2 border-transparent focus:border-emerald-500 outline-none transition-all"
          />
        </label>
      </section>

      {/* Categories Adjustment */}
      <section className="bg-white p-6 rounded-2xl border border-slate-100 shadow-sm space-y-6">
        <div className="flex justify-between items-center">
          <h3 className="text-slate-500 text-sm font-semibold uppercase tracking-widest">Distribuição (%)</h3>
          <button 
            onClick={handleReset}
            className="text-slate-400 hover:text-emerald-600 transition-colors flex items-center gap-1 text-xs font-medium"
          >
            <RefreshCcw size={14} /> Resetar
          </button>
        </div>

        <div className="space-y-5">
          {categories.map((cat) => (
            <div key={cat.id} className="space-y-2">
              <div className="flex justify-between items-center">
                <span className="text-sm font-medium text-slate-700">{cat.name}</span>
                <div className="flex items-center gap-2">
                  <input 
                    type="number" 
                    value={cat.percentage}
                    onChange={(e) => handlePercentageChange(cat.id, e.target.value)}
                    className="w-16 text-center font-bold p-1 bg-slate-50 border border-slate-200 rounded-lg focus:ring-1 focus:ring-emerald-500 outline-none"
                  />
                  <span className="text-slate-400 text-sm">%</span>
                </div>
              </div>
              <input 
                type="range" 
                min="0" 
                max="100" 
                value={cat.percentage}
                onChange={(e) => handlePercentageChange(cat.id, e.target.value)}
                className="w-full h-2 bg-slate-100 rounded-lg appearance-none cursor-pointer accent-emerald-500"
              />
            </div>
          ))}
        </div>

        {/* Validation Alert */}
        <div className={`p-4 rounded-xl flex items-center gap-3 transition-colors ${isValid ? 'bg-emerald-50 text-emerald-700' : 'bg-red-50 text-red-700'}`}>
          {isValid ? (
            <>
              <Save size={18} />
              <span className="text-sm font-medium">Total: {totalPercentage}% (Perfeito!)</span>
            </>
          ) : (
            <>
              <AlertCircle size={18} />
              <span className="text-sm font-medium">
                O total deve ser 100%. Atualmente: {totalPercentage}% 
                ({totalPercentage < 100 ? `faltam ${100 - totalPercentage}%` : `excesso de ${totalPercentage - 100}%`})
              </span>
            </>
          )}
        </div>
      </section>

      {/* Save Button */}
      <button 
        onClick={() => onSave(salary, categories)}
        disabled={!isValid}
        className={`w-full p-4 rounded-2xl font-bold flex items-center justify-center gap-2 transition-all shadow-lg active:scale-[0.98] ${isValid ? 'bg-emerald-600 hover:bg-emerald-700 text-white' : 'bg-slate-200 text-slate-400 cursor-not-allowed'}`}
      >
        <Save size={20} />
        Aplicar Configurações
      </button>
    </div>
  );
};

import React from 'react';
import { HistoryRecord } from '../types';
import { Trash2, Calendar, ChevronRight } from 'lucide-react';

interface HistoryProps {
  history: HistoryRecord[];
  onClear: () => void;
}

export const History: React.FC<HistoryProps> = ({ history, onClear }) => {
  const formatCurrency = (value: number) => {
    return new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(value);
  };

  return (
    <div className="space-y-6 animate-fadeIn">
      <div className="flex justify-between items-center">
        <h2 className="text-slate-500 text-sm font-semibold uppercase tracking-widest">Registros Passados</h2>
        {history.length > 0 && (
          <button 
            onClick={onClear}
            className="text-red-500 hover:bg-red-50 p-2 rounded-lg transition-colors flex items-center gap-2 text-xs font-medium"
          >
            <Trash2 size={16} /> Limpar Tudo
          </button>
        )}
      </div>

      {history.length === 0 ? (
        <div className="bg-white p-12 rounded-3xl border-2 border-dashed border-slate-200 flex flex-col items-center justify-center text-center space-y-4">
          <Calendar size={48} className="text-slate-200" />
          <div>
            <p className="text-slate-800 font-semibold">Nenhum registro ainda</p>
            <p className="text-slate-400 text-sm">Salve seu planejamento mensal na aba Dashboard clicando em 'Registrar Mês'.</p>
          </div>
        </div>
      ) : (
        <div className="space-y-4">
          {history.map((record) => (
            <div key={record.id} className="bg-white rounded-2xl border border-slate-100 shadow-sm overflow-hidden transition-all hover:border-emerald-200">
              <div className="bg-slate-50 p-4 flex justify-between items-center border-b border-slate-100">
                <span className="font-bold text-slate-800 capitalize">{record.date}</span>
                <span className="text-emerald-700 font-bold">{formatCurrency(record.salary)}</span>
              </div>
              <div className="p-4 space-y-2">
                {record.allocations.map((alloc, idx) => (
                  <div key={idx} className="flex justify-between items-center text-sm">
                    <span className="text-slate-500 flex items-center gap-2">
                      <ChevronRight size={14} className="text-slate-300" />
                      {alloc.name}
                    </span>
                    <div className="text-right">
                      <span className="text-slate-400 text-xs mr-2">{alloc.percentage}%</span>
                      <span className="font-medium text-slate-700">{formatCurrency(alloc.value)}</span>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Category } from '../types';
import { Save, AlertCircle, RefreshCcw } from 'lucide-react';

interface SettingsProps {
  initialSalary: number;
  initialCategories: Category[];
  onSave: (salary: number, categories: Category[]) => void;
}

export const Settings: React.FC<SettingsProps> = ({ initialSalary, initialCategories, onSave }) => {
  // Estado para o valor numérico puro
  const [salary, setSalary] = useState<number>(initialSalary);
  // Estado para o texto exibido no input (formatado)
  const [salaryInput, setSalaryInput] = useState<string>('');
  const [categories, setCategories] = useState<Category[]>(initialCategories);
  const [totalPercentage, setTotalPercentage] = useState<number>(0);

  // Inicializa o input formatado ao carregar
  useEffect(() => {
    setSalaryInput(formatCurrencyInput(initialSalary));
  }, [initialSalary]);

  useEffect(() => {
    const total = categories.reduce((acc, cat) => acc + cat.percentage, 0);
    setTotalPercentage(total);
  }, [categories]);

  // Função para formatar número para padrão brasileiro R$ (sem o prefixo R$)
  function formatCurrencyInput(value: number): string {
    return value.toLocaleString('pt-BR', {
      minimumFractionDigits: 2,
      maximumFractionDigits: 2,
    });
  }

  // Função para lidar com a mudança no input de salário (máscara de dinheiro)
  const handleSalaryChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    let value = e.target.value.replace(/\D/g, ''); // Remove tudo que não é dígito
    const numericValue = Number(value) / 100; // Converte para decimal

    setSalary(numericValue);
    setSalaryInput(formatCurrencyInput(numericValue));
  };

  const handlePercentageChange = (id: string, value: string) => {
    const numValue = Math.max(0, Math.min(100, Number(value) || 0));
    setCategories(prev => prev.map(cat => 
      cat.id === id ? { ...cat, percentage: numValue } : cat
    ));
  };

  const handleReset = () => {
    const defaultSalary = 3000;
    setSalary(defaultSalary);
    setSalaryInput(formatCurrencyInput(defaultSalary));
    setCategories(initialCategories.map(cat => ({ ...cat, percentage: 25 })));
  };

  const isValid = totalPercentage === 100;

  return (
    <div className="space-y-6 animate-fadeIn pb-10">
      {/* Salary Input Section */}
      <section className="bg-white p-6 rounded-2xl border border-slate-100 shadow-sm space-y-4">
        <div className="block">
          <span className="text-slate-500 text-sm font-semibold uppercase tracking-widest mb-3 block">Salário Mensal (R$)</span>
          <div className="relative group">
            <span className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 font-bold text-xl transition-colors group-focus-within:text-emerald-500">R$</span>
            <input 
              type="text" 
              inputMode="numeric"
              value={salaryInput}
              onChange={handleSalaryChange}
              placeholder="0,00"
              className="w-full text-2xl font-bold pl-14 pr-4 py-4 bg-slate-50 rounded-xl border-2 border-transparent focus:border-emerald-500 focus:bg-white outline-none transition-all text-slate-800"
            />
          </div>
          <p className="text-[10px] text-slate-400 mt-2 px-1 italic">Digite os números e os centavos serão ajustados automaticamente.</p>
        </div>
      </section>

      {/* Categories Adjustment */}
      <section className="bg-white p-6 rounded-2xl border border-slate-100 shadow-sm space-y-6">
        <div className="flex justify-between items-center">
          <h3 className="text-slate-500 text-sm font-semibold uppercase tracking-widest">Distribuição (%)</h3>
          <button 
            onClick={handleReset}
            className="text-slate-400 hover:text-emerald-600 transition-colors flex items-center gap-1 text-xs font-medium px-2 py-1 rounded-lg hover:bg-slate-50"
          >
            <RefreshCcw size={14} /> Resetar
          </button>
        </div>

        <div className="space-y-6">
          {categories.map((cat) => (
            <div key={cat.id} className="space-y-3 p-3 rounded-xl hover:bg-slate-50 transition-colors border border-transparent hover:border-slate-100">
              <div className="flex justify-between items-center">
                <span className="text-sm font-semibold text-slate-700 flex items-center gap-2">
                  <span className="w-2 h-2 rounded-full" style={{ backgroundColor: cat.color }}></span>
                  {cat.name}
                </span>
                <div className="flex items-center gap-2">
                  <div className="relative">
                    <input 
                      type="number" 
                      value={cat.percentage}
                      onChange={(e) => handlePercentageChange(cat.id, e.target.value)}
                      className="w-20 text-right font-bold py-1.5 pl-2 pr-6 bg-white border border-slate-200 rounded-lg focus:ring-2 focus:ring-emerald-500 focus:border-emerald-500 outline-none transition-all text-slate-800"
                    />
                    <span className="absolute right-2 top-1/2 -translate-y-1/2 text-slate-400 text-xs font-bold">%</span>
                  </div>
                </div>
              </div>
              <input 
                type="range" 
                min="0" 
                max="100" 
                step="1"
                value={cat.percentage}
                onChange={(e) => handlePercentageChange(cat.id, e.target.value)}
                className="w-full h-2 bg-slate-200 rounded-lg appearance-none cursor-pointer accent-emerald-500 transition-all hover:bg-slate-300"
              />
            </div>
          ))}
        </div>

        {/* Validation Alert */}
        <div className={`p-4 rounded-xl flex items-center gap-3 transition-all duration-300 ${isValid ? 'bg-emerald-50 text-emerald-700 border border-emerald-100' : 'bg-red-50 text-red-700 border border-red-100'}`}>
          {isValid ? (
            <div className="flex items-center gap-3 w-full">
              <div className="bg-emerald-500 p-1 rounded-full text-white">
                <Save size={14} strokeWidth={3} />
              </div>
              <span className="text-sm font-bold">Total: {totalPercentage}% (Distribuição Válida!)</span>
            </div>
          ) : (
            <div className="flex items-center gap-3 w-full">
              <AlertCircle size={20} className="shrink-0" />
              <div className="flex flex-col">
                <span className="text-sm font-bold">O total deve ser exatamente 100%</span>
                <span className="text-xs opacity-80">
                  Atual: {totalPercentage}% | {totalPercentage < 100 ? `Faltam ${100 - totalPercentage}%` : `Sobram ${totalPercentage - 100}%`}
                </span>
              </div>
            </div>
          )}
        </div>
      </section>

      {/* Save Button */}
      <div className="sticky bottom-4 z-10 px-2">
        <button 
          onClick={() => onSave(salary, categories)}
          disabled={!isValid}
          className={`w-full p-4 rounded-2xl font-bold flex items-center justify-center gap-2 transition-all shadow-xl active:scale-[0.98] ${isValid ? 'bg-emerald-600 hover:bg-emerald-700 text-white transform hover:-translate-y-1' : 'bg-slate-200 text-slate-400 cursor-not-allowed shadow-none'}`}
        >
          <Save size={20} />
          Salvar e Aplicar
        </button>
      </div>
    </div>
  );
};
